<?= $this->extend('layouts/admin') ?><?= $this->section('content') ?><section class="list-head"><div><p>Content assets</p><h1>Media library</h1></div></section><form class="upload-form" method="post" enctype="multipart/form-data" action="<?= site_url('admin/media') ?>"><?= csrf_field() ?><label>Image file<input type="file" name="file" accept="image/jpeg,image/png,image/webp" required></label><label>Alternative text <input name="alt_text" maxlength="255" placeholder="Describe the image; leave blank only when decorative"></label><button class="primary">Upload image</button><span>JPG, PNG or WebP · 10 MB / 40 megapixels max</span></form><div class="media-grid"><?php foreach ($media as $item): ?><figure><img src="<?= esc($item['path']) ?>" alt="<?= esc($item['alt_text'] ?? '') ?>"><figcaption><strong><?= esc($item['filename']) ?></strong><code><?= esc($item['path']) ?></code><form method="post" action="<?= site_url('admin/media/' . $item['id']) ?>"><?= csrf_field() ?><label>Alternative text<input name="alt_text" maxlength="255" value="<?= esc($item['alt_text'] ?? '') ?>"></label><button type="submit">Save description</button></form></figcaption></figure><?php endforeach ?><?php if (! $media): ?><p>No uploaded images yet. Legacy images are available in <code>/assets/media/</code>.</p><?php endif ?></div><?= $this->endSection() ?>
